    34  static flb_sds_t sds_alloc(size_t size)
    35  {
    36      void *buf;
    37      flb_sds_t s;
    38      struct flb_sds *head;
    39
    40      buf = flb_malloc(FLB_SDS_HEADER_SIZE + size + 1);
    41      if (!buf) {
    42          flb_errno();
    43          return NULL;
    44      }
    45
    46      head = buf;
    47      head->len = 0;
    48      head->alloc = size;
    49
    50      s = head->buf;
    51      *s = '\0';
    52
    53      return s;
    54  }
    55
    56  flb_sds_t flb_sds_create_len(const char *str, int len)
    57  {
    58      flb_sds_t s;
    59      struct flb_sds *head;
    60
    61      s = sds_alloc(len);
    62      if (!s) {
    63          return NULL;
    64      }
    65
    66      if (str) {
    67          memcpy(s, str, len);
    68          s[len] = '\0';
    69
    70          head = FLB_SDS_HEADER(s);
    71          head->len = len;
    72      }
    73      return s;
    74  }
    75
    76  flb_sds_t flb_sds_create(const char *str)
    77  {
    78      size_t len;
    79
    80      if (!str) {
    81          len = 0;
    82      }
    83      else {
    84          len = strlen(str);
    85      }
    86
    87      return flb_sds_create_len(str, len);
    88  }
    89
    90  flb_sds_t flb_sds_create_size(size_t size)
    91  {
    92      return sds_alloc(size);
    93  }
    94
    95  /* Increase SDS buffer size 'len' bytes */
    96  flb_sds_t flb_sds_increase(flb_sds_t s, size_t len)
    97  {
    98      size_t new_size;
    99      struct flb_sds *head;
   100      flb_sds_t out;
   101      void *tmp;
   102
   103      out = s;
   104      new_size = (FLB_SDS_HEADER_SIZE + flb_sds_alloc(s) + len + 1);
   105      head = FLB_SDS_HEADER(s);
   106      tmp = flb_realloc(head, new_size);
   107      if (!tmp) {
   108          flb_errno();
   109          return NULL;
   110      }
   111      head = (struct flb_sds *) tmp;
   112      head->alloc += len;
   113      out = head->buf;
   114
   115      return out;
   116  }
   117
   118  flb_sds_t flb_sds_cat(flb_sds_t s, const char *str, int len)
   119  {
   120      size_t avail;
   121      struct flb_sds *head;
   122      flb_sds_t tmp = NULL;
   123
   124      avail = flb_sds_avail(s);
   125      if (avail < len) {
   126          tmp = flb_sds_increase(s, len);
   127          if (!tmp) {
   128              return NULL;
   129          }
   130          s = tmp;
   131      }
   132      memcpy((char *) (s + flb_sds_len(s)), str, len);
   133
   134      head = FLB_SDS_HEADER(s);
   135      head->len += len;
   136      s[head->len] = '\0';
   137
   138      return s;
   139  }
