    26  #ifndef FLB_SDS_H
    27  #define FLB_SDS_H
    28
    29  #include <fluent-bit/flb_info.h>
    30  #include <fluent-bit/flb_macros.h>
    31  #include <stdlib.h>
    32  #include <string.h>
    33  #include <inttypes.h>
    34
    35  #define FLB_SDS_HEADER_SIZE (sizeof(uint64_t) + sizeof(uint64_t))
    36
    37  typedef char *flb_sds_t;
    38
    39  #pragma pack(push, 1)
    40  struct flb_sds {
    41      uint64_t len;        /* used */
    42      uint64_t alloc;      /* excluding the header and null terminator */
    43      char buf[];
    44  };
    45  #pragma pack(pop)
    46
    47  #define FLB_SDS_HEADER(s)  ((struct flb_sds *) (s - FLB_SDS_HEADER_SIZE))
    48
    49  static inline size_t flb_sds_len(flb_sds_t s)
    50  {
    51      return (size_t) FLB_SDS_HEADER(s)->len;
    52  }
    53
    54  static inline int flb_sds_is_empty(flb_sds_t s)
    55  {
    56      if (flb_sds_len(s) == 0) {
    57          return FLB_TRUE;
    58      }
    59
    60      return FLB_FALSE;
    61  }
    62
    63  static inline void flb_sds_len_set(flb_sds_t s, size_t len)
    64  {
    65      FLB_SDS_HEADER(s)->len = len;
    66  }
    67
    68  static inline size_t flb_sds_alloc(flb_sds_t s)
    69  {
    70      return (size_t) FLB_SDS_HEADER(s)->alloc;
    71  }
    72
    73  static inline size_t flb_sds_avail(flb_sds_t s)
    74  {
    75      struct flb_sds *h;
    76
    77      h = FLB_SDS_HEADER(s);
    78      return (size_t) (h->alloc - h->len);
    79  }
    80
    81  static inline int flb_sds_cmp(flb_sds_t s, const char *str, int len)
    82  {
    83      if (flb_sds_len(s) != len) {
    84          return -1;
    85      }
    86
    87      return strncmp(s, str, len);
    88  }
    89
    90  static inline int flb_sds_casecmp(flb_sds_t s, const char *str, int len)
    91  {
    92      if (flb_sds_len(s) != len) {
    93          return -1;
    94      }
    95
    96      return strncasecmp(s, str, len);
    97  }
